param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs)
$root=Join-Path $ScratchRoot ('canteen-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:HIBERNATION_SESSION_KEY='canteen-process-session';$env:HIBERNATION_CANTEEN_FIXTURE='synthetic-canteen-provider';$env:TEMP=Join-Path $root tmp;$env:TMP=$env:TEMP;New-Item -ItemType Directory -Force $env:TEMP|Out-Null
$provider=$null;$desktop=$null;$service=$null;$checks=[Collections.Generic.List[string]]::new()
function Check($v,$name){if(!$v){throw "CHECK FAILED: $name"};$checks.Add($name);Write-Output "PASS $name"}
function Wait-For([scriptblock]$probe,$name,[int]$seconds=35){$end=[DateTime]::UtcNow.AddSeconds($seconds);while([DateTime]::UtcNow-lt$end){if(& $probe){return};if($service-and$service.HasExited){throw 'Synthetic backend exited'};Start-Sleep -Milliseconds 60};throw "TIMEOUT $name"}
function Api($path,$data=$null){$a=@{Uri=$script:origin+$path;Headers=@{Authorization='Bearer canteen-process-session'};TimeoutSec=10};if($null-ne$data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @a}
function Kitchen{(Api '/api/capabilities').plugins.Where({$_.id-eq'canteen'})[0].current.current}
function World{(Api '/api/capabilities').plugins.Where({$_.id-eq'habitat'})[0].current}
function Activities{Api '/api/activities/status'}
function Plugin($name,$arguments){$null=Api '/api/plugin/test' @{tool=$name;args=$arguments};Wait-For {$script:last=Api '/api/plugin/result';$last.state-in@('succeeded','failed')} $name;return $script:last.result}
function Start-Backend{Remove-Item (Join-Path $root ready.json) -ErrorAction SilentlyContinue;$script:desktop=[PrivateDesktop]::new($Executable,(Join-Path $root config.json),(Join-Path $root ready.json),$ProjectRoot);$script:service=$desktop.Child;Wait-For {Test-Path (Join-Path $root ready.json)} ready;$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(15000)-and$service.ExitCode-eq0) 'clean encrypted shutdown';$desktop.Dispose();$script:desktop=$null;$script:service=$null}
function Plan($responses){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($responses|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root provider/plan.json) -Encoding utf8}
function Tool($name,$arguments){@{version=1;kind='call';text=$null;calls=@(@{id='fixture';tool=$name;args=$arguments})}}
function Message($text){$id=[Guid]::NewGuid().ToString('N');$null=Api '/api/message' @{request_id=$id;text=$text};Wait-For {!(Api '/api/chat').busy} 'foreground complete'}
function Reply{@{version=1;kind='reply';text='先准备一杯茶。';calls=@();presentation=@{speech=$false;bubble=$false}}}
try{
 $provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root provider.log) -RedirectStandardError (Join-Path $root provider-error.log);Wait-For {Test-Path (Join-Path $root provider/port)} 'fake provider'
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path (Split-Path $Executable) plugins;$cfg.frontend.startupAnimation=$false;$cfg.solitudeIntervalMs=86400000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.maxStartsPerHour=1000;$cfg.maxToolRounds=4;$cfg.review=@{enabled=$false};$cfg.reflectOnActivities=$false
 $cfg.plugins=@{widget=@{enabled=$true;roam=$false;autonomousMode=$true;autonomyIdleSeconds=600};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;maxObjects=3;lifetimeMinSeconds=5;lifetimeMaxSeconds=600;reducedMotion=$true};canteen=@{enabled=$true;automatic=$false;automaticIntervalSeconds=900;supplyIntervalSeconds=3600;shelfLifeSeconds=1800}}
 $cfg.profiles+=@{id='fixture';label='Canteen fixture';enabled=$true;protocol='chat-completions';origin=('http://127.0.0.1:'+(Get-Content (Join-Path $root provider/port)));basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_CANTEEN_FIXTURE';supportsStreaming=$false;supportsJsonSchema=$false;supportsJsonObject=$true;timeoutMs=10000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root config.json) -Encoding utf8
 Start-Backend;$null=Api '/api/model' @{id='fixture'};Wait-For {(World).desktop} 'private desktop ready'
 Check ((Kitchen).menu.Count-eq3-and(Kitchen).shelf.Count-eq0) 'plugin publishes actual menu and empty shelf';Check (@((Api '/api/capabilities').tools|Where-Object tool -eq canteen.cook).Count-eq1) 'model discovers kitchen tools without user naming them'
 $bad=Plugin 'canteen.cook' @{recipe_id='bread';ingredient_ids=@('flour','sugar','water')};Check (!$bad.ok-and$bad.error.code-eq'canteen_ingredients_mismatch') 'invalid recipe cannot consume pantry';$bad=Plugin 'canteen.cook' @{recipe_id='tea';nutrition=999};Check (!$bad.ok) 'model cannot forge food numeric effects'
 $first=Plugin 'canteen.cook' @{recipe_id='bread';ingredient_ids=@('butter','flour','water')};Check ($first.ok-and!$first.result.completed-and(Kitchen).shelf.Count-eq0) 'valid reordered recipe starts but does not claim completion'
 $busy=Plugin 'canteen.cook' @{recipe_id='tea'};Check (!$busy.ok-and$busy.error.code-eq'canteen_busy') 'only one cooking position'
 $cancel=Plugin 'canteen.cancel' @{job_id=$first.result.job.id};Check ($cancel.ok-and(Kitchen).pantry.Where({$_.id-eq'flour'})[0].available-eq4) 'cancel releases original material reservation'
 Plan @((Tool 'canteen.cook' @{recipe_id='tea'}),(Reply));Message '我想留一杯茶等会儿再喝。';Check ((Kitchen).job.recipe_id-eq'tea'-and(Kitchen).job.origin-eq'character') 'real model loop uses plugin and retains character authorship'
 $null=Api '/api/control' @{paused=$true};$frozen=Kitchen;Start-Sleep -Milliseconds 400;Check ((Kitchen).job.remaining_seconds-eq$frozen.job.remaining_seconds) 'pause freezes cooking and freshness'
 Stop-Backend;Start-Backend;Check ((Kitchen).job.id-eq$frozen.job.id-and(Kitchen).job.remaining_seconds-eq$frozen.job.remaining_seconds) 'backend restart restores exact pending craft without elapsed offline work'
 $null=Api '/api/control' @{paused=$false};Wait-For {(Kitchen).shelf.Count-eq1} 'actual tea completion' 25;$meal=(Kitchen).shelf[0];Check ($meal.recipe_id-eq'tea'-and$meal.sensory.basis-eq'program_simulated_food_properties') 'completed meal carries authored sensory provenance'
 $null=Plugin 'habitat.create' @{kind='paper_star'};$null=Plugin 'habitat.create' @{kind='crystal'};$null=Plugin 'habitat.create' @{kind='leaf'}
 $take=Plugin 'canteen.take' @{batch_id=$meal.id};Check ($take.ok-and!$take.result.completed) 'take is an asynchronous publication request';Wait-For {!(Kitchen).delivery_pending} 'full desktop rejection';Check ((Kitchen).shelf.Count-eq1-and(Kitchen).shelf[0].id-eq$meal.id-and(World).objects.Count-eq3) 'failed desktop delivery preserves the exact shelf meal'
 # Existing objects expire shortly after a config change only if born with that
 # lifetime. Consume their actual edible object, then reuse the freed position.
 $leaf=(World).objects.Where({$_.kind-eq'leaf'})[0];$act=Plugin 'habitat.act' @{id=$leaf.id;action='eat'};Check $act.ok 'existing desktop food remains usable';Wait-For {(World).objects.Count-eq2} 'leaf eaten' 35
 $take=Plugin 'canteen.take' @{batch_id=$meal.id};Wait-For {(Kitchen).shelf.Count-eq0-and(World).objects.Count-eq3} 'published meal confirmation';$food=(World).objects.Where({$_.creator-eq'canteen'})[0];Check ($food.provenance.batch_id-eq$meal.id-and$food.provenance.recipe_id-eq'tea') 'actual desktop meal retains the kitchen batch identity';Check ($food.rules.nutrition-eq6) 'program template controls nutrition independently of model text'
 $duplicate=Plugin 'canteen.take' @{batch_id=$meal.id};Check (!$duplicate.ok-and(World).objects.Count-eq3) 'completed serving cannot be duplicated'
 $null=Api '/api/control' @{paused=$true};$id=$food.id;Stop-Backend;Start-Backend;Check ((World).objects.Where({$_.id-eq$id}).Count-eq1-and(Kitchen).shelf.Count-eq0) 'served food survives restart without returning to shelf';$null=Api '/api/control' @{paused=$false}
 $eat=Plugin 'habitat.act' @{id=$id;action='eat'};Check $eat.ok 'character can approach and consume actual prepared food';Wait-For {(World).objects.Where({$_.id-eq$id}).Count-eq0} 'meal consumed' 35
 # Cached sequence must wait for the actual cooked batch, then publish it.
 Plan @((Tool 'activity.enqueue' @{commands=@(@{kind='canteen_cook';recipe_id='tea'},@{kind='take_meal';recipe_id='tea'})}),(Reply));Message '再泡一杯，做好后放到桌边。';Wait-For {(Activities).active.kind-eq'canteen_cook'} 'cached cooking begins';Check ((Kitchen).shelf.Count-eq0) 'queued cook is not prematurely completed';Wait-For {$a=Activities;$a.queued-eq0-and$null-eq$a.active-and(World).objects.Where({$_.creator-eq'canteen'}).Count-eq1} 'cached cook then take sequence' 30;Check (@((Activities).recent|Where-Object {$_.kind-in@('canteen_cook','take_meal')-and$_.status-eq'completed'}).Count-eq2) 'autonomous sequence finishes from real kitchen outcomes'
 $null=Api '/api/control' @{paused=$true};Stop-Backend
 $db=[IO.File]::ReadAllBytes((Join-Path $root data/archive/records.sqlite));Check (![Text.Encoding]::UTF8.GetString($db).Contains('program_simulated_food_properties')) 'food provenance and kitchen state remain encrypted in archive'
 @{completed=$true;checks=$checks;count=$checks.Count;root=$root;productionDataUsed=$false;realPaidCalls=0}|ConvertTo-Json -Depth 7|Set-Content (Join-Path $root acceptance.json) -Encoding utf8
}catch{try{@{error=$_.Exception.Message;kitchen=Kitchen;world=World;activities=Activities}|ConvertTo-Json -Depth 40|Set-Content (Join-Path $root failure.json) -Encoding utf8}catch{};throw}finally{if($desktop){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(10000)|Out-Null}catch{};if($service-and!$service.HasExited){$service.Kill()};$desktop.Dispose()};if($provider-and!$provider.HasExited){Stop-Process -Id $provider.Id -Force}}
